import React, { useState, useMemo, useEffect } from "react";
import { Link, useLocation } from "@tanstack/react-router";
import { FaSearch } from "react-icons/fa";

const BlogsList = ({ listdData }) => {
  const [searchTerm, setSearchTerm] = useState("");
  const location = useLocation();
  const currentPath = location.pathname;

  // Track which categories are open.
  const [openCategories, setOpenCategories] = useState({});

  // Automatically expand the active category when currentPath or listdData changes
  useEffect(() => {
    if (listdData && Array.isArray(listdData)) {
      listdData.forEach((item) => {
        if (item[1] && (currentPath === `/${item[1]}` || currentPath.startsWith(`/${item[1]}/`))) {
          setOpenCategories((prev) => {
            if (!prev[item[1]]) {
              return { ...prev, [item[1]]: true };
            }
            return prev;
          });
        }
      });
    }
  }, [currentPath, listdData]);

  // Memoize filtered data so we don't recalculate on every render
  const filteredData = useMemo(() => {
    if (!listdData) return [];
    if (!searchTerm) return listdData;
    return listdData.filter((item) => {
      const mainCat = item[0]?.toLowerCase() || "";
      const subCats = item[2] ? item[2].map(s => s[0]?.toLowerCase() || "").join(" ") : "";
      return mainCat.includes(searchTerm.toLowerCase()) || subCats.includes(searchTerm.toLowerCase());
    });
  }, [listdData, searchTerm]);
  
  const handleCategoryClick = () => {
    // Only scroll on mobile/tablet screen sizes
    if (window.innerWidth < 1024) {
      setTimeout(() => {
        const productSection = document.getElementById("mainProductSection");
        if (productSection) {
          // Get navbar height to use as offset
          const navbar = document.getElementById("navbarContainer");
          const headerOffset = navbar ? navbar.offsetHeight + 20 : 100; // Adding 20px extra breathing room
          
          const elementPosition = productSection.getBoundingClientRect().top;
          const offsetPosition = elementPosition + window.pageYOffset - headerOffset;
 
          window.scrollTo({
            top: offsetPosition,
            behavior: "smooth"
          });
        }
      }, 150); // Small timeout allows router navigation to begin
    }
  };

  const toggleCategory = (categoryLink) => {
    setOpenCategories((prev) => ({
      ...prev,
      [categoryLink]: !prev[categoryLink],
    }));
  };

  return (
    <div className="w-full md:min-w-[230px] lg:min-w-[300px] h-fit transition-all duration-300 border-[#004B95] border-[1px] rounded-[10px] bg-white sticky top-24">
      <div className="box h-[5rem] w-fit pl-6 relative flex justify-start items-start group mt-5">
        <div className="h-12 w-1.5 bg-[#004B95] absolute mr-[1rem] origin-left group-hover:w-full duration-300 group"></div>
        <h3 className="text-[22px] font-bold text-[#004B95] mt-[0.5rem] ml-[0.7rem] group-hover:text-white group-hover:translate-x-5 duration-300 capitalize truncate pr-5">
          Categories
        </h3>
      </div>

      <div className="flex justify-between px-[20px] items-center relative border-[1px] border-[#004B95] rounded-[5px] h-[38px] mx-[10%] w-[80%]">
        <input
          type="text"
          name="catSearch"
          id="catSearch"
          onChange={(e) => setSearchTerm(e.target.value)}
          placeholder="Search here"
          className="font-medium leading-[30px] outline-none focus:outline-none tracking-[5%] text-[#004B95] w-[80%]"
        />
        <FaSearch className="text-[#004B95] relative inline-block" />
      </div>

      <ul className="w-full transition-all duration-300 mb-5 mt-[10px] px-[20px] flex flex-col gap-y-1">
        {filteredData.map((item, index) => {
          if (!item) return null;
          const hasSub = item[2] && item[2].length !== 0;
          const isOpen = !!openCategories[item[1]];

          return (
            <li
              key={item[1] || index}
              data-category={item[0] + "," + (item[2] ? item[2].join("|") : "")}
              className="category list-none relative w-full border-b-[2px] border-[#004a9533] last:border-b-0 py-2"
            >
              <div className="flex items-center justify-between">
                <Link
                  to={`/${item[1]}`}
                  title={item[0]}
                  onClick={(e) => {
                    handleCategoryClick();
                    if (hasSub) {
                      toggleCategory(item[1]);
                    }
                  }}
                  className={`font-poppins font-medium text-[1rem] leading-[30px] text-[#004B95] hover:font-bold transition-all duration-300 flex-grow truncate mr-2 ${
                    isOpen ? "font-bold" : ""
                  }`}
                >
                  {item[0]}
                </Link>
                {hasSub && (
                  <button
                    onClick={(e) => {
                      e.preventDefault();
                      e.stopPropagation();
                      toggleCategory(item[1]);
                    }}
                    className="p-1 focus:outline-none"
                    aria-label={isOpen ? "Collapse category" : "Expand category"}
                  >
                    <svg
                      fill="currentColor"
                      className={`bi bi-chevron-down w-4 h-4 text-kijeka-blue transition-transform duration-300 ${
                        isOpen ? "rotate-180" : ""
                      }`}
                      viewBox="0 0 16 16"
                    >
                      <path
                        fillRule="evenodd"
                        d="M1.646 4.646a.5.5 0 0 1 .708 0L8 10.293l5.646-5.647a.5.5 0 0 1 .708.708l-6 6a.5.5 0 0 1-.708 0l-6-6a.5.5 0 0 1 0-.708z"
                      />
                    </svg>
                  </button>
                )}
              </div>
              {hasSub && (
                <div
                  id="subCategory"
                  className={`w-full grid transition-all duration-300 ${
                    isOpen
                      ? "grid-rows-[1fr] opacity-100 mt-2 pointer-events-auto"
                      : "grid-rows-[0fr] opacity-0 pointer-events-none"
                  }`}
                >
                  <div className="overflow-hidden text-kijeka-blue">
                    <ul className="pl-4 pb-2 text-sm text-kijeka-blue flex flex-col gap-y-2">
                      {item[2].map((subItem, subIndex) => {
                        const isSubActive = currentPath === `/${item[1]}/${subItem[1]}`;
                        return (
                          <li key={subIndex} className="hover:font-bold">
                            <Link
                              to={`/${item[1]}/${subItem[1]}`}
                              onClick={handleCategoryClick}
                              className={`flex items-center py-1 transition-all duration-200 ${
                                isSubActive ? "font-bold underline" : ""
                              }`}
                            >
                              &#x2022;&nbsp;{subItem[0]}
                            </Link>
                          </li>
                        );
                      })}
                    </ul>
                  </div>
                </div>
              )}
            </li>
          );
        })}
      </ul>
    </div>
  );
};

export default BlogsList;

